/* the design system's style layer: brand color tokens, base/components/utilities,
   the faces, and the theme mapping. imported by platform (as source, alongside its own
   `@import "tailwindcss"`) and by ./build-entry.css (which adds that import
   itself to compile this package's standalone artifact). never import
   "tailwindcss" from this file — platform's compile needs to own that. */

@import "./fonts.css";
@import "./colors.css";
@import "./base.css";
@import "./components.css";
@import "./utilities.css";
@import "./theme.css";

/* this package's own components live outside every consumer's tree, so
   automatic content detection never reaches them — register the source here,
   relative to this file, so every consumer gets it for free on import
   instead of repeating the path against its own directory layout. must come
   after the @import block above — @import rules must precede all other
   at-rules in a stylesheet. */
@source "..";

@layer base {
  *,
  ::after,
  ::before,
  ::backdrop,
  ::file-selector-button {
    /* the token, not the step: `surface-primary` rebinds --border so a hairline
       inside a brand fill is drawn against that fill, and --ring so the focus
       ring is. reading gray-6/blue-8 here would leave both rebinds with no
       consumer. */
    border-color: var(--border);
    outline-color: var(--ring);
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    font-family: var(--font-display);
    font-weight: 700;
  }

  body {
    font-family: var(--font-body);
    color: var(--gray-12);
  }

  a {
    &[aria-disabled="true"] {
      pointer-events: none;
      cursor: not-allowed;
    }
  }

  button {
    &:disabled {
      cursor: not-allowed;
    }
  }
}

/* the height of a form control, declared once so it is reachable.
   `.field-input` composes to exactly this out of padding + line-height +
   border (14 + 20 + 14 + 2) — arithmetic nothing else can match without
   copying the number. `btn-field` in styles/utilities.css reads the same var,
   so a button sitting beside a field cannot drift from it.
   `.field-input` pins itself to it below, which is a no-op today and the point:
   change this and the field follows, instead of the arithmetic silently
   disagreeing. */
:root {
  --field-size: calc(var(--spacing) * 12.5) /* 50px */;
}

@layer components {
  /* bare .btn is the md tier of the size scale — py-2 / px-6 / text-sm / 36px.
     the other two tiers (btn-sm, btn-lg) and btn-md live in utilities.css as
     @utility so they are variant-capable (`xl:btn-lg`) and win this layer.
     radius is var(--radius) (6px), the control corner of the two (a
     container's is --radius-card); an integer step, since a fractional corner
     shows against .btn-secondary's 1px edge. */
  .btn {
    display: flex;
    justify-content: center;
    align-items: center;
    font-weight: 700;
    /* published for btn-icon, which squares a button on its tier's own height.
       bare .btn carries no tier class, so the md value has to live here too. */
    --btn-size: calc(var(--spacing) * 9) /* 36px */;
    padding-block: calc(var(--spacing) * 2);
    padding-inline: calc(var(--spacing) * 6);
    font-size: var(--text-sm) /* 0.875rem = 14px */;
    line-height: var(--tw-leading, var(--text-sm--line-height));
    min-block-size: var(--btn-size);
    border-radius: var(--radius);
  }

  /* the neutral control on radix's roles: steps 3 / 4 / 5 are its fill at
     rest / hovered / pressed, and 7 / 8 its edge at rest / hovered — the
     interactive-border rungs, the same two a field's edge (--input /
     --input-hover) points at. spelled as the steps rather than as those
     tokens: --input names a field's edge, and a button's is not one. */
  .btn-secondary {
    background-color: var(--gray-3);
    color: var(--gray-12);
    border: 1px solid var(--gray-7);
    &:hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: var(--gray-4);
      border-color: var(--gray-8);
    }
    /* same specificity as the hover and after it, so a press reads over a
       hover rather than under it. */
    &:active:not(:disabled):not([aria-disabled="true"]) {
      background-color: var(--gray-5);
    }
  }

  /* a neutral control resting transparent: no step at rest, 4 hovered, 5
     pressed. */
  .btn-ghost {
    background-color: transparent;
    color: inherit;
    &:hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: var(--gray-4);
    }
    &:active:not(:disabled):not([aria-disabled="true"]) {
      background-color: var(--gray-5);
    }
    &:disabled {
      background-color: var(--gray-3);
      color: var(--gray-11);
    }
  }

  /* the filled variants below share one fill between :hover and :active: the
     ramp gives a solid two steps, not three, so there is no third rung to press
     to. the press reads as a 1px downward nudge instead — the affordance a
     scale can't supply, and on touch, where there is no hover, the only
     acknowledgement a tap gets. */
  .btn-primary {
    background-color: var(--primary);
    color: var(--primary-fg);
    &:active {
      background-color: var(--primary-hover);
      transform: translateY(1px);
    }
    &:hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: var(--primary-hover);
    }
  }

  .btn-destructive {
    background-color: var(--destructive);
    color: var(--destructive-fg);
    &:active {
      background-color: var(--destructive-hover);
      transform: translateY(1px);
    }
    &:hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: var(--destructive-hover);
    }
  }

  .btn-success {
    background-color: var(--success);
    color: var(--success-fg);
    &:active {
      background-color: var(--success-hover);
      transform: translateY(1px);
    }
    &:hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: var(--success-hover);
    }
  }

  .btn-warning {
    background-color: var(--warning);
    color: var(--warning-fg);
    &:active {
      background-color: var(--warning-hover);
      transform: translateY(1px);
    }
    &:hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: var(--warning-hover);
    }
  }

  /* the filled button on a brand fill: --primary on --primary (or on
     --primary-deep) is no button at all, so it inverts to the fill's own ink.
     no hover rung — the --primary-fg alpha ladder is unmeasured
     (design-system.md, "--primary-fg alpha steps") — so it keeps only the
     filled variants' press. its ring is below the shared one. */
  .btn-inverse {
    background-color: var(--primary-fg);
    color: var(--primary);
    &:active {
      transform: translateY(1px);
    }
  }

  /* an outline button that takes its color from the surface it sits on. the
     four call sites this replaces each hand-spelled the band's ink a second
     time — `border-2 border-primary-fg/40 text-primary-fg hover:bg-primary-fg/10`,
     or the same shape in raw white over a photo hero — on a container that had
     already declared that ink for its own copy. writing it twice is what lets
     it drift once. currentColor reads whatever the surface set: --primary-fg
     on a `surface-primary` band, gray-12 from the body rule on the page,
     white over a hero.

     the mixes are oklab, not oklch, to match what tailwind's own `/40` and
     `/10` opacity modifiers compile to — an oklch mix down to transparent
     takes a different path and would not reproduce the call sites it
     replaces. */
  .btn-outline {
    background-color: transparent;
    color: inherit;
    border: 2px solid color-mix(in oklab, currentColor 40%, transparent);
    &:hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: color-mix(in oklab, currentColor 10%, transparent);
    }
    &:active {
      background-color: color-mix(in oklab, currentColor 15%, transparent);
    }
  }

  /* one focus indicator for every variant. the per-variant outline colors this
     replaces were tints of the button's own fill and were invisible against it;
     one ring for every variant is the fix, and the offset is what makes it
     work rather than the color. --ring is the ramp's step 8, Lc 44.6 against
     the page — clear of the Lc 30 a focus indicator needs, taken as radix
     assigns it. on a .btn-primary fill it measures Lc 30.0, on that line and
     not over it, which is why the offset stays and why a
     --primary-filled panel still scopes with `surface-primary`. */
  .btn,
  .btn-sm,
  .btn-md,
  .btn-lg,
  .btn-ghost,
  .btn-outline,
  .btn-secondary,
  .btn-success,
  .btn-primary,
  .btn-warning,
  .btn-destructive {
    &:focus-visible {
      outline: 2px solid var(--ring);
      outline-offset: 2px;
    }
  }

  /* the inverse button's ring is --primary-ring whatever scope it sits in: the
     offset puts the ring on the brand fill around it, where --ring (blue-8)
     does not read. after the shared ring, so it wins at equal specificity. */
  .btn-inverse:focus-visible {
    outline-color: var(--primary-ring);
  }

  .btn-outline,
  .btn-secondary,
  .btn-success,
  .btn-primary,
  .btn-warning,
  .btn-destructive {
    &:disabled {
      background-color: var(--gray-3);
      color: var(--gray-11);
    }
  }

  /* the in-flight rung, and it is deliberately the disabled fill: a control
     that is submitting must not be submitted again, so it reads the same as
     one that cannot be pressed. it was authored per-variant and only ever on
     three of the six, plus a duplicate pair under `a.btn-*` — reachable on
     half the set and inert on the other half. one block covers every variant
     and both element forms.
     `pointer-events: none` because the state is set by the component rather
     than by the element's own `:disabled`, which would stop the click itself.
     nothing here is reachable at rest: `.pending` is a class the component
     writes only while a submission is in flight. */
  .btn-primary,
  .btn-secondary,
  .btn-ghost,
  .btn-outline,
  .btn-destructive,
  .btn-success,
  .btn-warning {
    &.pending {
      background-color: var(--gray-3);
      color: var(--gray-11);
      pointer-events: none;
    }
  }

  a.btn-secondary,
  a.btn-warning,
  a.btn-success,
  a.btn-primary,
  a.btn-ghost,
  a.btn-outline,
  a.btn-destructive {
    &[aria-disabled="true"] {
      background-color: var(--gray-3);
      color: var(--gray-11);
    }
  }

  .field-input {
    width: 100%;
    border-radius: var(--radius);
    font-size: var(--text-sm) /* 0.875rem = 14px */;
    line-height: var(
      --tw-leading,
      var(--text-sm--line-height) /* calc(1.25 / 0.875) ≈ 1.4286 */
    );
    background-color: var(--surface);
    padding: calc(var(--spacing) * 3.5) calc(var(--spacing) * 4);
    min-block-size: var(--field-size);
    /* --input, radix's interactive-border step 7 (under 1.4.11's 3:1 by PM
       decision, packages/brand/src/colors.css). the hover leaves an invalid
       field's destructive edge alone. */
    border: 1px solid var(--input);
    outline-color: var(--ring);
    color: var(--gray-12);

    &:hover:not(
        :disabled,
        [readonly],
        [aria-disabled="true"],
        :user-invalid,
        [aria-invalid="true"]
      ) {
      border-color: var(--input-hover);
    }

    &::placeholder {
      color: var(--gray-11);
    }
    /* biome-ignore lint/style/noDescendingSpecificity: unrelated to a.btn-* selectors */
    &[aria-disabled="true"],
    &[readonly],
    &:disabled {
      pointer-events: none;
      background-color: var(--gray-3);
      color: var(--gray-11);
    }

    /* :user-invalid, never :invalid — :invalid paints every required-but-empty
       field destructive on first paint, before the field has been touched. */
    &:user-invalid,
    &[aria-invalid="true"] {
      @apply border-destructive;
    }
  }

  .field-input-container {
    width: 100%;
    border-radius: var(--radius);
    font-size: var(--text-sm) /* 0.875rem = 14px */;
    line-height: var(
      --tw-leading,
      var(--text-sm--line-height) /* calc(1.25 / 0.875) ≈ 1.4286 */
    );
    background-color: var(--surface);
    border: 1px solid var(--input);
    color: var(--gray-12);

    &:hover:not(
        :has(
          input:disabled,
          input[readonly],
          input[aria-disabled="true"],
          input:user-invalid,
          input[aria-invalid="true"]
        )
      ) {
      border-color: var(--input-hover);
    }

    &:has(input:focus) {
      outline: solid;
      outline-width: 2px;
      outline-color: var(--ring);
    }

    &:has(input::placeholder) {
      color: var(--gray-11);
    }
    &:has(input[aria-disabled="true"]),
    &:has(input[readonly]),
    &:has(input:disabled) {
      pointer-events: none;
      background-color: var(--gray-3);
      color: var(--gray-11);
    }

    &:has(input:user-invalid),
    &:has(input[aria-invalid="true"]) {
      @apply border-destructive;
    }
  }

  .field-err {
    text-align: right;
    font-size: var(--text-xs);
    color: var(--destructive);
  }

  .selector-btn {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  /* zag's select item emits data-state="checked"|"unchecked", data-highlighted
     and data-disabled — never data-selected. data-highlighted is the keyboard
     equivalent of :hover, so arrow navigation has to key off it or the pointer
     is the only way to see where you are. a tinted option rests transparent,
     hovers at the tint's step 4 and is selected at its step 5. */
  .selector-opt {
    padding: calc(var(--spacing) * 2) calc(var(--spacing) * 4);
    &[data-state="checked"] {
      background-color: var(--secondary-active);
    }
    &[data-highlighted] {
      background-color: var(--secondary-hover);
    }
    &:hover {
      background-color: var(--secondary-hover);
    }
  }

  .label {
    display: block;
    font-size: var(--text-sm);
    font-weight: var(--font-weight-medium);
    &[data-required="true"]::after {
      content: " *";
      color: var(--destructive);
    }
    &[data-required="false"]::after {
      content: " (optional)";
      color: var(--gray-11);
      font-weight: normal;
      font-size: 0.8em;
    }
  }

  .label-floating {
    position: absolute;
    left: 0;
    color: var(--ring);
    transition: transform var(--duration-base) var(--ease-out);
    /* the field's own fill: the raised label straddles the field's top edge,
       and its lower half sits on the field. */
    background-color: var(--surface);
    padding-right: var(--spacing);
    font-weight: var(--font-weight-semibold);
    font-size: var(--text-xs);
    bottom: calc(100% - 0.5lh);

    &[data-required="true"]::after {
      content: " *";
      color: var(--destructive);
    }
    &[data-required="false"]::after {
      content: " (optional)";
      color: var(--gray-11);
      font-weight: normal;
      font-size: 0.8em;
    }
  }

  /* the label at rest: sitting inside the control, at input size. the raised
     position is `.label-floating`'s own declarations above, so rest is the only
     state that needs a rule.

     keyed off the field root with `:has()` rather than an adjacent sibling: a
     control that wraps its input in a subtree (a combobox's root → control →
     input) has no sibling relationship to the label at all, and the recipe has
     to reach those too.

     rest and focus are mutually exclusive by construction — a focused empty
     input still shows its placeholder, so `:not(:has(input:focus))` withholds
     rest there and the raised declarations stand. nothing turns on which rule
     is written last. */
  :has(input:placeholder-shown):not(:has(input:focus)) > .label-floating {
    left: calc(var(--spacing) * 4);
    font-weight: normal;
    background-color: transparent;
    bottom: 50%;
    transform: translateY(50%);
    font-size: var(--text-sm);
    color: var(--gray-11);
  }

  /* a data table is a card with its inset delegated: the card's fill, edge
     and corner on the table itself, so a table on the page needs no wrapper to
     be one. its header row sits on the card's own tone, as radix themes'
     table does, and is told by its ink and the rule under it; row and column
     lines are --hairline, the line inside a card. the table is the shell
     rather than its scroller because several tables have no scroller at all;
     inside a `table-scroll` the shell moves to the scroller (below).
     `separate` borders are what let a table take a border-radius. */
  .table {
    --table-fill: var(--card);
    /* the control corner, not the card's: a 12px curve clips the header
       row's first and last labels (PM, 2026-11-02). */
    --table-corner: var(--radius);
    min-width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    font-feature-settings: "tnum", "zero";
    background-color: var(--table-fill);
    border-radius: var(--table-corner);
    border: 1px solid var(--hairline);

    & th {
      font-weight: var(--font-weight-medium);
      font-size: var(--text-sm);
      line-height: var(--text-sm--line-height);
      color: var(--gray-11);
    }

    /* the header row is a well on the table's fill: step 3 on step 2, so
       the labels read apart from the rows under them (PM, 2026-11-02). */
    /* biome-ignore lint/style/noDescendingSpecificity: unrelated to the shell selectors above */
    & thead th {
      background-color: var(--panel);
    }

    & tbody tr {
      font-size: var(--text-sm);
      line-height: var(--text-sm--line-height);
    }

    /* row dividers */
    & :is(tbody, tfoot) > tr > :is(th, td) {
      border-top: 1px solid var(--hairline);
    }

    & :is(th, td) {
      padding: calc(var(--spacing) * 2);
      text-align: left;
    }

    /* a filled row (a hovered or tinted one) paints in its cells' boxes, which
       are square: the four corner cells take the shell's corner so the fill
       stays inside it. --table-corner is 0 wherever the table is not its own
       shell, so these fall away with it. first/last row group by sibling
       rather than :first-child, which a <caption> or <colgroup> would take. */
    &
      > :is(thead, tbody, tfoot):not(:is(thead, tbody, tfoot) ~ *)
      > tr:first-child {
      & > :first-child {
        border-start-start-radius: var(--table-corner);
      }
      & > :last-child {
        border-start-end-radius: var(--table-corner);
      }
    }
    &
      > :is(thead, tbody, tfoot):not(:has(~ :is(thead, tbody, tfoot)))
      > tr:last-child {
      & > :first-child {
        border-end-start-radius: var(--table-corner);
      }
      & > :last-child {
        border-end-end-radius: var(--table-corner);
      }
    }

    /* a money or count column: header and cells both carry `num`, so the
       figures line up on the decimal and the label sits over them. */
    & :is(th, td).num {
      text-align: right;
    }

    /* the load-more row: a neutral control resting transparent, 4 hovered and
       5 pressed. */
    & tfoot button {
      font-size: var(--text-xs);
      font-weight: var(--font-weight-semibold);
      width: 100%;
      /* the load-more row is the table's last: its hover fill keeps the corner */
      border-end-start-radius: var(--table-corner);
      border-end-end-radius: var(--table-corner);
      padding: calc(var(--spacing) * 2);
      display: flex;
      align-items: center;
      justify-content: center;
      gap: calc(var(--spacing) * 2);
      /* biome-ignore lint/style/noDescendingSpecificity: unrelated to .btn-* selectors */
      &:hover:not(:disabled):not([aria-disabled="true"]) {
        background-color: var(--gray-4);
      }
      /* biome-ignore lint/style/noDescendingSpecificity: unrelated to .btn-* selectors */
      &:active {
        background-color: var(--gray-5);
      }
      /* biome-ignore lint/style/noDescendingSpecificity: unrelated to .btn-* selectors */
      &:disabled,
      /* biome-ignore lint/style/noDescendingSpecificity: unrelated to a.btn-* selectors */
        &[aria-disabled="true"] {
        background-color: var(--gray-3);
        color: var(--gray-11);
      }
    }
  }

  /* a table already inside a card, or a dialog, is content of that surface: no
     second fill, edge or corner. same specificity as `.table`, so it has to
     stay after it. */
  :where(.card, [role="dialog"]) .table {
    --table-fill: transparent;
    --table-corner: 0;
    border-width: 0;
  }

  /* a table in a `table-scroll` hands its shell to the scroller: the
     scroller's box is the table's box, and its overflow is what rounds the
     table's corners. `>` so only the scroller directly around the table takes
     it, never an outer wrapper. */
  .table-scroll:has(> .table) {
    background-color: var(--card);
    border-radius: var(--radius);
    border: 1px solid var(--hairline);
  }
  .table-scroll > .table {
    --table-fill: transparent;
    --table-corner: 0;
    border-width: 0;
  }
  /* in a card or dialog the scroller is content too. after the rule above,
     same specificity. */
  :where(.card, [role="dialog"]) .table-scroll:has(> .table) {
    background-color: transparent;
    border-radius: 0;
    border-width: 0;
  }
}

/* `rounded` is the repo's one radius name in app code — `rounded-full` and
   `rounded-none` aside, which v4 emits from literals. tailwind v4 ships it as
   a hardcoded 0.25rem with no theme variable behind it (only the suffixed
   `rounded-xs|sm|md|lg|...` read
   `--radius-*`), so the bare utility would not follow `--radius` if that ever
   moved. rebinding it here is the documented way to customize a built-in
   utility, and makes the name the app already uses the single source.
   `rounded-sm`/`-xs` are not the escape hatch they look like: the `--radius-*`
   scale they read is reset to `initial` in theme.css, so they fail to compile. */
@utility rounded {
  border-radius: var(--radius);
}

/* side-specific corners at the same one radius. v4 derives `rounded-b`/`-r`
   from the --radius-* scale, and that scale is reset to `initial` in theme.css
   so a stray `rounded-sm` can't compile — which takes these down with it
   unless they're bound here too. same value, same rule, just two corners. */
@utility rounded-t {
  border-start-start-radius: var(--radius);
  border-start-end-radius: var(--radius);
}
@utility rounded-b {
  border-end-start-radius: var(--radius);
  border-end-end-radius: var(--radius);
}
@utility rounded-l {
  border-start-start-radius: var(--radius);
  border-end-start-radius: var(--radius);
}
@utility rounded-r {
  border-start-end-radius: var(--radius);
  border-end-end-radius: var(--radius);
}

/* the container's corner — `card`, `solo-card`, and every layer over the page:
   dialog, menu, popover, select list, hovercard, toast. bound here for the
   same reason `rounded` is: the --radius-* scale is reset in theme.css, so a
   theme-derived `rounded-card` would not exist. a control or a well inside a
   card keeps `rounded`; the smaller corner nested in the larger one is what
   reads as "inside". */
@utility rounded-card {
  border-radius: var(--radius-card);
}

/* the three named speeds from theme.css, as the names a call site writes.
   tailwind's own `duration-*` is a bare-value utility with no theme namespace
   behind it, so there is no scale to declare a ladder in and none to reset:
   `duration-200` compiles regardless, and the sweep is what rejects it. these
   three exist so that a transition which needs to say a speed out loud has a
   name to say it with, and so the value moves in one place. a transition that
   wants the house speed says nothing at all and reads
   --default-transition-duration. */
@utility duration-fast {
  transition-duration: var(--duration-fast);
}
@utility duration-base {
  transition-duration: var(--duration-base);
}
@utility duration-slow {
  transition-duration: var(--duration-slow);
}

@utility date-input {
  &::-webkit-calendar-picker-indicator {
    @apply absolute w-full opacity-0;
  }
}

@utility field-error {
  @apply absolute -bottom-5 right-0 text-xs text-right text-destructive;
}

/* focus-visible, never focus — the house trigger, the same one `.btn` and every
   `btn-*` variant carry in styles/components.css. `focus:` here rings the
   control on a pointer press and the button beside it stays unringed: browsers
   withhold :focus-visible from a pointer press on a checkbox or radio, and
   grant it to every keyboard one, so the narrower trigger costs a keyboard user
   nothing.
   the text controls keep `:focus` and are not a hole in that rule: a pointer
   press on an <input> DOES match :focus-visible, so `.field-input-container`'s
   `:has(input:focus)` in styles/components.css is the same set of moments under
   another name. ledger entry in packages/brand/design-system.md →
   "Which states each control carries". */
@utility radio {
  @apply flex items-center gap-4 data-[required=true]:after:ml-1 data-[required=true]:after:content-['*'] data-[required=true]:after:text-destructive;
  & > input {
    @apply appearance-none h-4 relative aspect-square border border-input hover:border-input-hover bg-surface rounded-full before:content-[''] before:h-2.5 before:aspect-square before:absolute before:top-1/2 before:left-1/2 before:-translate-x-1/2 before:-translate-y-1/2 before:rounded-full checked:before:bg-primary disabled:checked:before:bg-gray-3 focus-visible:outline-2 focus-visible:outline-ring;
  }
}
/* drawn, not `accent-*`: the UA box carries its own edge and ignores --input,
   so it sat beside every field on the page in a different grey. the check is
   two borders of a rotated box, so it takes --primary-fg like any other ink on
   the fill and needs no image. */
@utility checkbox {
  @apply appearance-none relative size-4 shrink-0 rounded border border-input bg-surface not-disabled:hover:border-input-hover checked:bg-primary checked:border-primary before:hidden checked:before:block before:absolute before:top-1/2 before:left-1/2 before:-mt-0.5 before:w-1.5 before:h-2.5 before:-translate-x-1/2 before:-translate-y-1/2 before:rotate-45 before:border-r-2 before:border-b-2 before:border-primary-fg disabled:bg-gray-3 disabled:border-hairline disabled:before:border-gray-11 focus-visible:outline-2 focus-visible:outline-ring;
  &:checked:not(:disabled):hover {
    background-color: var(--primary-hover);
    border-color: var(--primary-hover);
  }
}

@utility check-field {
  @apply grid grid-cols-[auto_1fr] justify-items-start gap-x-3 items-center;
  & > label {
    @apply data-[required=true]:after:ml-1 data-[required=true]:after:content-['*'] data-[required=true]:after:text-destructive;
  }
  & > input {
    @apply checkbox;
  }
  & > [data-error] {
    @apply col-span-full text-xs text-destructive;
  }
}

/* button size scale. authored as @utility, not @layer components, for two
   reasons: only @utility classes are variant-capable, and 11+ call sites switch
   size responsively (`xl:btn-lg`); and the utilities layer beats .btn's
   components layer regardless of source order. bare .btn is the md tier —
   btn-md is a name only, so a button can step *down* (`btn-lg md:btn-md`).
   heights are the natural content box; the pin stops an icon-only button or a
   line-height change from shrinking the control below its tier. */

@utility btn-sm {
  --btn-size: calc(var(--spacing) * 6) /* 24px */;
  padding-block: calc(var(--spacing) * 1) /* 4px */;
  padding-inline: calc(var(--spacing) * 3) /* 12px */;
  font-size: var(--text-xs) /* 0.75rem = 12px */;
  line-height: var(--tw-leading, var(--text-xs--line-height) /* 1rem = 16px */);
  /* 4 + 16 + 4 = exactly 24px, zero natural headroom — the pin, not the
     arithmetic, is what holds WCAG 2.2 SC 2.5.8 Target Size (Minimum), AA,
     24x24 css px. px-3 alone clears the width floor; pinned anyway for the
     icon-only case. */
  min-block-size: var(--btn-size);
  min-inline-size: var(--btn-size);
}

@utility btn-md {
  --btn-size: calc(var(--spacing) * 9) /* 36px */;
  padding-block: calc(var(--spacing) * 2) /* 8px */;
  padding-inline: calc(var(--spacing) * 6) /* 24px */;
  font-size: var(--text-sm) /* 0.875rem = 14px */;
  line-height: var(--tw-leading, var(--text-sm--line-height) /* 20px */);
  min-block-size: var(--btn-size);
}

@utility btn-lg {
  --btn-size: calc(var(--spacing) * 13) /* 52px */;
  padding-block: calc(var(--spacing) * 3) /* 12px */;
  padding-inline: calc(var(--spacing) * 8) /* 32px */;
  font-size: var(--text-lg) /* 1.125rem = 18px */;
  line-height: var(--tw-leading, var(--text-lg--line-height) /* 28px */);
  min-block-size: var(--btn-size);
}

/* the fourth tier, and the only one whose height is not its own: a button that
   sits BESIDE a form control and has to match it — the show/copy buttons next
   to an api-key field. --field-size is declared in styles/components.css and is
   what `.field-input` pins itself to, so this tracks the field by construction
   rather than by a copied number. everything else mirrors btn-md. */
@utility btn-field {
  --btn-size: var(--field-size);
  padding-block: calc(var(--spacing) * 2) /* 8px */;
  padding-inline: calc(var(--spacing) * 6) /* 24px */;
  font-size: var(--text-sm) /* 0.875rem = 14px */;
  line-height: var(--tw-leading, var(--text-sm--line-height) /* 20px */);
  min-block-size: var(--btn-size);
  /* a field-height button sits in a row with fields, so it is exactly their
     height rather than at least it: border-box, so the border is inside. */
  block-size: var(--btn-size);
}

/* square icon-only shape. a modifier, not a fourth tier: it composes with all
   three sizes (`btn-sm btn-icon`, `btn btn-icon`, `btn-lg btn-icon`) and takes
   its side from the tier's own height, published as --btn-size. must stay AFTER
   the three tiers in this file — same layer, same specificity, so source order
   is what lets it win padding-inline. bare .btn is in the components layer and
   loses to this regardless of order. inline-size and min-inline-size are both
   set so the square survives being a flex item that could otherwise shrink.
   the button has no text node, so every call site MUST carry an aria-label.
   radius is inherited from .btn (var(--radius)) — do not add a second one.
   block-size is definite, not a min: a flex row defaults to align-items:stretch,
   and a min-block-size does not stop it — only a definite size wins over
   stretch, so beside a taller control the square survives. it also
   leaves the item at cross-start, so a row mixing this with a taller control
   needs `items-center` on the CONTAINER — alignment is external flow and stays
   the caller's, per the layout rule in CLAUDE.md. */
@utility btn-icon {
  padding-inline: 0;
  inline-size: var(--btn-size);
  min-inline-size: var(--btn-size);
  block-size: var(--btn-size);
}

/* a bare glyph acting as a button — a lucide icon with no label and no box of
   its own. deliberately NOT a .btn modifier: that is btn-icon, and it only
   works ON a .btn, whose 36px min-block-size, bold weight and px-6 come with
   it. all of that is a control's chrome, wrong around a naked glyph, and it
   pins the smallest possible target at 36px when the floor is 24. this tier
   contributes hit area and nothing else, so color, hover and focus classes
   stay the call site's.
   24px is WCAG 2.2 SC 2.5.8 Target Size (Minimum), AA — the same floor btn-sm
   pins itself to, reached here by the min alone since the glyph is always
   smaller than the box. mins rather than definite sizes so a larger glyph
   still grows its own target.
   flex-shrink is baked in: these sit in flex rows beside text that would
   otherwise squeeze the target back under the floor.
   the button has no text node, so every call site MUST carry an aria-label
   unless the underlying library already supplies one (zag's toast
   CloseTrigger does). */
@utility glyph-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-inline-size: calc(var(--spacing) * 6) /* 24px */;
  min-block-size: calc(var(--spacing) * 6) /* 24px */;
  border-radius: var(--radius);
}

/* icon size ladder, for lucide glyphs. css inline-/block-size beat the svg's
   own width/height attributes, so the class alone sets the box. flex-shrink is baked in for the reason glyph-btn bakes it:
   an svg is overflow:hidden, so its flex min-size is 0 and a row of text beside
   it squeezes the glyph. ledger entry in packages/brand/design-system.md. */
@utility icon-xs {
  inline-size: calc(var(--spacing) * 3) /* 12px */;
  block-size: calc(var(--spacing) * 3) /* 12px */;
  flex-shrink: 0;
}

@utility icon-sm {
  inline-size: calc(var(--spacing) * 3.5) /* 14px */;
  block-size: calc(var(--spacing) * 3.5) /* 14px */;
  flex-shrink: 0;
}

@utility icon-md {
  inline-size: calc(var(--spacing) * 4) /* 16px */;
  block-size: calc(var(--spacing) * 4) /* 16px */;
  flex-shrink: 0;
}

@utility icon-lg {
  inline-size: calc(var(--spacing) * 4.5) /* 18px */;
  block-size: calc(var(--spacing) * 4.5) /* 18px */;
  flex-shrink: 0;
}

@utility icon-xl {
  inline-size: calc(var(--spacing) * 5) /* 20px */;
  block-size: calc(var(--spacing) * 5) /* 20px */;
  flex-shrink: 0;
}

@utility icon-2xl {
  inline-size: calc(var(--spacing) * 6) /* 24px */;
  block-size: calc(var(--spacing) * 6) /* 24px */;
  flex-shrink: 0;
}

/* pictogram ladder, a second closed set for the same lucide glyphs. an icon is
   sized against the text beside it; a pictogram is sized against the surface it
   heads — a feature mark atop a marketing card, or the outcome check or alert
   that IS a panel's or page's message. neither ladder reaches the other's job,
   which is why there are two. ledger entry in packages/brand/design-system.md. */
@utility pictogram-sm {
  inline-size: calc(var(--spacing) * 7.5) /* 30px */;
  block-size: calc(var(--spacing) * 7.5) /* 30px */;
  flex-shrink: 0;
}

@utility pictogram-md {
  inline-size: calc(var(--spacing) * 10) /* 40px */;
  block-size: calc(var(--spacing) * 10) /* 40px */;
  flex-shrink: 0;
}

@utility pictogram-lg {
  inline-size: calc(var(--spacing) * 20) /* 80px */;
  block-size: calc(var(--spacing) * 20) /* 80px */;
  flex-shrink: 0;
}

@utility btn-donate {
  border-radius: var(--radius);
  text-transform: none;
}

@utility btn-form-primary {
  background-color: var(--form-primary);
  color: var(--primary-fg);
  /* --ring, not --secondary: --secondary is a near-white tint at Lc 0.0
     against the page, under what apca can measure. --ring is remapped to
     --form-primary inside #donation-container, so the ring follows
     the host org's brand rather than pinning a value that may collide with an
     unknown host page. */
  &:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  &:hover:not(:disabled):not([aria-disabled="true"]) {
    background-color: color-mix(in oklch, var(--form-primary) 90%, black);
  }
  &:active {
    background-color: color-mix(in oklch, var(--form-primary) 85%, black);
  }
  &:disabled {
    background-color: var(--gray-3);
    color: var(--gray-11);
  }
  /* the in-flight rung, matching the six variants in components.css. it cannot
     be picked up from there: --form-primary is a tenant value and this tier is
     the only thing that paints it, so a fill it does not restate stays the
     tenant's brand while the control is submitting. */
  &.pending {
    background-color: var(--gray-3);
    color: var(--gray-11);
    pointer-events: none;
  }
}

/* the link primitive: a run of text that navigates. ink, hover ink and focus —
   the whole of a text link's treatment — and nothing else. size, weight,
   spacing and display stay the caller's, the same split the type roles keep
   below.

   both rungs are the ramp's, read off the state ladder's filled row rather than
   picked: step 9 at rest, step 10 hovered. `--primary` is the ledger's one
   blessed ink for a text-only control; `--primary-hover` is the step the solid
   variants already hover to, so a link and a button move together.

   the hover is that colour shift and nothing else, in every context — an
   underline that appears or disappears on hover is not this recipe. a RESTING
   underline is still the caller's and sixteen sites keep one.

   no `:not([aria-disabled="true"])` guard on the hover, unlike the button
   variants: `styles/base.css` gives a disabled anchor `pointer-events: none`,
   so the hover cannot fire and the call site's `aria-disabled:text-gray-11`
   outranks both rules anyway.

   focus-visible, never focus — the house trigger, the same one `.btn` and every
   control in styles/components.css carries. stated in full rather than left to
   the UA outline that `styles/base.css` already colours: the width and the
   offset are the ledger's focus row, and a UA outline has neither.

   a link whose ink is NOT the brand colour is a different thing and keeps its
   own: the contrast ink on a brand fill (the footer, the announcement banner),
   the error ink in a destructive band. `link-conformance.node.test.ts` names
   that set. */
@utility link {
  color: var(--primary);
  &:hover {
    color: var(--primary-hover);
  }
  &:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}

/* a band or panel filled with --primary. use instead of bare `bg-primary`
   whenever the fill contains a control: it rebinds --ring and --border for
   everything inside, because the page-level values are drawn against the page
   and neither is picked to sit on a brand fill. --ring is the ramp's step 8
   and no longer equals --primary — it went from vanishing into the fill to
   merely being quiet on it, so this rebind is a smaller win than it was and
   still the right one. same mechanism as #donation-container's --ring remap in
   platform's index.css. */
@utility surface-primary {
  background-color: var(--primary);
  color: var(--primary-fg);
  --ring: var(--primary-ring);
  --border: var(--primary-border);
}

/* the page shape — one name, one width curve, one gutter. layout is the one
   axis with no closed-set gate behind it: `--color-*` and `--radius-*` are
   reset to `initial` in theme.css so an off-system spelling compiles to
   nothing, but a made-up width compiles fine and just looks slightly wrong.
   this name is that gate, enforced by a filesystem sweep instead of by the
   compiler.

   the curve is tailwind's own `container` ladder, spelled out rather than
   inherited: full-bleed until the laptop rung, 80rem from there, 96rem on a
   large monitor. that behaviour is right and is kept exactly — a page should
   widen with the window. what the name buys is the gutter, which was
   hand-spelled ~40 times as `xl:container xl:mx-auto px-*` with a different
   value almost every time (px-5, px-10, px-24, max-sm:px-10). that spread is
   why a header and the sections under it never shared an edge.

   there is no second, narrower shape. reading measure is not a page width —
   it is a cap on the text column itself, one level in: `max-w-3xl` on the
   paragraph block, or `prose`, which carries its own 65ch. a page width that
   also tried to be a reading measure just moved the whole layout in and left
   the header behind.

   width and gutter only — no background, no vertical rhythm. a band that
   paints a full-bleed fill is the caller's own element wrapping this one, and
   it must not also carry a `px-*`: two gutters stack. a page that alternates
   full-bleed bands with contained ones therefore puts this on each band, never
   hoisted onto a shared parent. */
@utility page {
  @apply w-full mx-auto px-5 md:px-10;
  @media (width >= 80rem) {
    max-inline-size: 80rem /* 1280px */;
  }
  @media (width >= 96rem) {
    max-inline-size: 96rem /* 1536px */;
  }
}

/* the in-flow container: a marketing card, a dashboard tile, a figure, a
   callout, a link tile. the fill, the edge, the corner and the inset — the
   shell's half of the ownership rule in packages/brand/design-system.md — and
   nothing else.

   radix's card: step 2 (`bg-card`) with a step-6 edge (`border-hairline`, the
   edge of something you can't operate) and no shadow. the edge is what finds
   it on the step-1 page, on a marketing page and on a `bg-band` alike, so
   there is one card for every ground. a line INSIDE a card is the same
   --hairline (`border-hairline`, `divide-hairline`).

   the inset is one value in every role — no tier, and no per-file variant —
   and one step per width: 16px on a phone, 24px from md, the same breakpoint
   where the page gutter widens (PM, 2026-11-02).

   no layout and no type. `grid`, `flex`, a `gap`, a `divide-y`, a heading size
   are the arrangement of the contents, and the arrangement stays the caller's
   — the same split `solo-card` records below. a card that needs an outer
   margin takes it from the caller too.

   a surface with no inset has delegated it and is a different shell — a table
   shell, a `divide-y` list, an `overflow-hidden` media frame. it spells the
   same fill, edge and corner itself, and `shell-conformance.node.test.ts` is
   written to leave it alone. */
@utility card {
  @apply bg-card rounded-card border border-hairline p-4 md:p-6;
}

/* the card that is the whole of a single-purpose screen — login, signup,
   check-email, and the five password-reset panels each sit alone on an
   otherwise empty page in exactly this shape. not a narrower `page`: that one
   is a width and a gutter for a full layout, this is one card with its own
   fill and edge, on the same step-1 page as every other screen.

   no gap and no `justify-items`, both deliberately. the ten it collapsed
   space their children with per-child `mt-*`, so a gap here would add to those
   margins rather than replace them; and they split evenly on whether their
   content is centred, which makes alignment the caller's to say. */
@utility solo-card {
  @apply grid w-full max-w-md px-4 sm:px-7 py-7 sm:py-8 bg-card rounded-card border border-hairline;
}

/* the scrollbar skin. tailwind 4.3 ships `scrollbar-width`/`scrollbar-color`
   natively, and the three that dress a scroller here were always written as
   one breath — 59 times, on the x axis, the y axis and both. one name, so a
   new scroller cannot be half-skinned. axis is deliberately not included:
   this is decoration, and the caller still says which way its content runs. */
@utility scrollbars {
  @apply scrollbar-thin scrollbar-thumb-ring scrollbar-track-gray-6;
}

/* the cue that a sideways row runs past its box: an edge fade on whichever
   side still has more to scroll, the sidebar label's right-edge mask made
   conditional. scroll-driven, so it costs no script and shows only while the
   row overflows — with nothing to scroll the timeline is inactive, no keyframe
   applies and both fades sit at their 0px initial value. without
   `animation-timeline` the row still scrolls, unfaded, which is the guard's
   job: an unsupported timeline would run the keyframes as a 0s animation and
   pin the end state, a fade on the left at rest. the fade is 16 steps wide so a
   label cut at the box edge dissolves instead of reading as clipped. */
@property --scroll-fade-start {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}
@property --scroll-fade-end {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}
@keyframes scroll-fade-x {
  0% {
    --scroll-fade-start: 0px;
    --scroll-fade-end: calc(var(--spacing) * 16);
  }
  10%,
  90% {
    --scroll-fade-start: calc(var(--spacing) * 16);
    --scroll-fade-end: calc(var(--spacing) * 16);
  }
  100% {
    --scroll-fade-start: calc(var(--spacing) * 16);
    --scroll-fade-end: 0px;
  }
}
@utility scroll-fade-x {
  @supports (animation-timeline: scroll()) {
    mask-image: linear-gradient(
      to right,
      transparent,
      black var(--scroll-fade-start),
      black calc(100% - var(--scroll-fade-end)),
      transparent
    );
    animation: scroll-fade-x linear both;
    animation-timeline: scroll(self inline);
    /* the fade's full width: a child scrolled into view (a focused tab) stops
       clear of the faded edge rather than under it */
    scroll-padding-inline: calc(var(--spacing) * 16);
  }
}

/* the wrapper a wide table sits in. a table is the one thing on a dashboard
   that cannot reflow — the columns are the data — so past a narrow viewport it
   either scrolls sideways or pushes the whole page wider and takes the sidebar
   with it. put this on the element wrapping the `<table>`, never on the table.

   36 files spelled it out identically; it carried the same three skin classes
   every time and the axis every time. structure stays the caller's: a `grid`,
   a `col-span-full`, a background or a margin on the same element are all
   fine, and none of them competes with what this sets. the fill, edge and
   corner around a `.table` directly inside are drawn on this box, by
   components.css, so its overflow rounds the table's corners.

   it is also the inline-size container `EmptyRow` measures, so a table's one
   empty line centres in the visible width rather than across the full scroll
   width, where a narrow screen cuts it off.

   and it is the containing block: an absolutely positioned cell child (an
   `sr-only` header label) otherwise resolves against the page, sits outside
   the scroller's clip and widens the page at a phone width. */
@utility table-scroll {
  @apply overflow-x-auto scrollbars relative;
  container-type: inline-size;
}

/* position only. the corner is the layer's: a dialog box takes `rounded-card`
   from helpers/modal-box.ts, and a bare frame says its own. */
@utility fixed-center {
  @apply fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2;
}

/* the row a form's or a dialog's terminal controls sit in: the submit, and
   whatever sits beside it.

   `actions` and `actions-split` are two complete rows, not a base and a
   modifier: they are never written together, and the second is not a
   `justify-*` laid over the first. two utilities of equal specificity resolve
   by stylesheet source order, not class-string order, so an override written
   beside the base is a coin flip — the same reason the vertical rhythm is not
   overridable on EmptyState. the geometry is therefore repeated in full, and
   the only thing that differs is where the free space goes.

   the stack at narrow is `flex-col` with no `items-*`, which leaves
   `align-items: stretch` — that is what makes the buttons full-width down
   there, with no child selector and no `w-full` on each control. `items-center`
   is scoped to `sm:` because it only means anything once the row is a row.

   no `text-align` belongs here: it does not reach a flex container's items,
   and `.btn` centers its own label anyway.

   `gap-4` is the spacing the dialog set sits at, and the row holds it at every
   width.

   `actions-band` is the dialog footer's fill and padding, and composes with
   either row. the fill is step 2, radix's subtle background, one rung under
   the step-1 dialog it closes; its top edge is --hairline, the line inside a
   surface. `empty:h-12` holds the band open when the footer renders no control
   at all. */
@utility actions {
  @apply flex max-sm:flex-col sm:items-center sm:justify-end gap-4 w-full;
}

@utility actions-split {
  @apply flex max-sm:flex-col sm:items-center sm:justify-between gap-4 w-full;
}

@utility actions-band {
  @apply p-3 sm:px-8 sm:py-4 bg-gray-2 border-t border-hairline empty:h-12;
}

@utility absolute-center {
  @apply absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2;
}

@utility flex-center {
  @apply flex items-center justify-center;
}

/* the named type roles. each one is a responsive size curve plus its wrapping
   behaviour — never color and never weight-of-voice, so a caller still says
   what the text IS on the page. the ladder they step through is closed in
   ./theme.css, so these are the sanctioned way to pick a heading size:
   reaching past them means naming a new role here, not spelling a step at the
   call site.

   tracking is the one spacing these roles do carry, and only where it is a
   function of the size rather than a voice: quicksand is drawn for text and
   its sidebearings read loose once the size curve reaches display rungs, so
   the correction differs per breakpoint. a call site cannot express that — it
   sees one class, not the rungs behind it — which is why it lives here with
   the curve it corrects. */

/* the one h1 at the top of a marketing page — the largest type in the product,
   and there is at most one per page. the display rung sets solid on the spacing
   ladder (4rem over 3.75rem, ≈1.07): /tight's 1.25 opens a gap between lines
   at this size that reads as two headings. quicksand's descender sits well
   inside the 4px left over, so nothing clips. */
@utility hero-heading {
  @apply text-3xl/tight md:text-4xl/tight lg:text-6xl/16 tracking-tight text-balance;
}

/* the h2 that opens a band further down a marketing page. one rung under the
   hero from sm up so a section never competes with the page's title; under sm
   it drops to 2xl, where 3xl ran a section's h2 to three lines at 390. */
@utility section-heading {
  @apply text-2xl/tight sm:text-3xl/tight md:text-4.5xl/tight tracking-tight text-balance;
}

/* the standfirst paragraph directly under a section-heading — larger than body
   copy because it is read as part of the heading, not as the section's prose.
   text-pretty rather than text-balance: it runs to several lines. */
@utility section-body {
  @apply text-lg md:text-2xl text-pretty;
}

/* a heading inside long-form prose — blog posts, legal pages, help copy. sits
   under section-heading because it divides a body of text rather than a page. */
@utility article-heading {
  @apply text-2xl md:text-3xl text-balance;
}

/* the lead-in line above a heading. distinct from `eyebrow` below: this one is
   larger and is not uppercased, so it carries a readable phrase rather than a
   kicker. */
@utility pre-heading {
  @apply text-sm md:text-lg font-bold;
}

/* the small uppercase label above a section heading — the canonical eyebrow.
   type only: color is the caller's (text-primary / text-gray-11 /
   text-secondary), as is any size override (text-2xs on dense surfaces).
   distinct from pre-heading, which is the larger lead-in that is not always
   uppercased. */
@utility eyebrow {
  @apply text-xs font-bold uppercase tracking-label;
}

/* aligned numbers — any figure that sits in a column, a total, or beside
   another figure a reader compares it to: money, counts, dates, percentages.

   both halves are inert today, and that is recorded rather than hidden.
   `tabular-nums` emits `font-variant-numeric: tabular-nums`, and Quicksand
   ships no `tnum` feature (checked against the binary with fontTools) — its
   digits are proportional, so a money column does not line up and cannot be
   made to under this face. `--font-display` meanwhile equals `--font-body`,
   so the family declaration changes nothing either.

   the utility earns its line as a seam, not as a rule that fires: it collapses
   every such call site into one name, so the day a face with real tabular figures is
   adopted this is a one-line change instead of a 22-site sweep. both halves
   are written out for that reason — a seam that is missing half the intent is
   a seam that gets re-derived wrong. */
@utility figures {
  font-family: var(--font-display);
  @apply tabular-nums;
}

@theme {
  --color-\*: initial;
  --color-transparent: transparent;
  --color-current: currentColor;
  --color-inherit: inherit;

  --color-black: #000101;

  --color-white: #ffffff;

  /* the size ladder is closed, the same way --color-* and --radius-* are: the
     twelve steps below are every one the three source trees use, and every
     other name compiles to nothing rather than drifting in. text-7xl/-8xl/-9xl
     are deliberately absent — a 72px/96px/128px step nobody picks is the far
     end of the same drift the radius reset closes at the near end.

     EVERY redeclared step carries its --text-<step>--line-height companion.
     that key lives inside this namespace, so the reset drops it too, and an
     unsuffixed `text-lg` would silently lose its line-height without it. the
     values are tailwind v4's own, copied unchanged: this closes the set, it
     does not retune it. --text-2xs and --text-4_5xl are ours and are
     deliberately UNPAIRED — neither has a default line height, and giving one
     now would move type that renders correctly.

     what the reset deliberately does not reach: text-balance/-pretty/-center/
     -ellipsis are static utilities with no theme behind them, text-<color>
     reads --color-*, and text-shadow-* is a sibling namespace v4 explicitly
     exempts from this clear. nor does it reach arbitrary values — text-[11px]
     still compiles, so bracket drift needs review, not the compiler. */
  --text-*: initial;
  --text-2xs: 0.625rem;
  --text-xs: 0.75rem;
  --text-xs--line-height: calc(1 / 0.75);
  --text-sm: 0.875rem;
  --text-sm--line-height: calc(1.25 / 0.875);
  --text-base: 1rem;
  --text-base--line-height: calc(1.5 / 1);
  --text-lg: 1.125rem;
  --text-lg--line-height: calc(1.75 / 1.125);
  --text-xl: 1.25rem;
  --text-xl--line-height: calc(1.75 / 1.25);
  --text-2xl: 1.5rem;
  --text-2xl--line-height: calc(2 / 1.5);
  --text-3xl: 1.875rem;
  --text-3xl--line-height: calc(2.25 / 1.875);
  --text-4xl: 2.25rem;
  --text-4xl--line-height: calc(2.5 / 2.25);
  /* the one authored step: `_` is how v4 spells a dot, so this is text-4.5xl */
  --text-4_5xl: 2.625rem;
  --text-5xl: 3rem;
  --text-5xl--line-height: 1;
  --text-6xl: 3.75rem;
  --text-6xl--line-height: 1;

  /* the weight ladder is closed to the four in use. font-extrabold and
     font-black are the point of it: Quicksand's wght axis stops at 700, so 800
     and 900 have only ever rendered as bold — an inert class that would go
     live, unreviewed, the day a heavier face is adopted. thin/extralight/light
     go for the reverse reason: nothing under 400 is legible at this face's
     low stroke contrast, and none of them carries a call site.
     `font-[550]` is still arbitrary and still compiles — names close, brackets
     do not. */
  --font-weight-*: initial;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* the leading ladder is closed to the four multipliers in use; loose (2) is
     absent, with no call site to keep it. values are tailwind v4's own,
     unchanged.
     `leading-none` is deliberately NOT declared and is NOT lost: v4 emits it
     from a static value (line-height: 1), not from this namespace, and the
     `/none` modifier on a text-* utility is likewise a literal. numeric
     leading (`leading-5`) is unaffected too — it derives from --spacing.
     so this reset closes the named multipliers and nothing else. */
  --leading-*: initial;
  --leading-tight: 1.25;
  --leading-snug: 1.375;
  --leading-normal: 1.5;
  --leading-relaxed: 1.625;

  /* the tracking ladder is closed. tighter (-0.05em), normal (0em) and
     widest (0.1em) are dropped as unused — normal especially, since it is the
     resting value and spelling it is always a no-op.
     label and badge are ours: tailwind's own ladder tops out at 0.1em and does
     not reach either value.
     label: standalone uppercase label — eyebrow, section kicker, column meta.
     badge: uppercase text inside a padded chip; tighter so the last glyph
     doesn't crowd the chip's right padding.
     tight, wide and wider stay because call sites exist. most of those sites
     are uppercase labels that belong on `label`/`badge` — a per-site judgment
     call, so that sweep is its own change; closing the namespace stops the
     drift growing in the meantime.
     widest goes with tighter and normal: no call sites, so retaining it as a
     reference point for the two authored values would be the same drift this
     reset exists to close, just with a nicer reason attached. */
  --tracking-*: initial;
  --tracking-tight: -0.025em;
  --tracking-wide: 0.025em;
  --tracking-wider: 0.05em;
  --tracking-label: 0.12em;
  --tracking-badge: 0.08em;

  /* two roles, ONE face. both resolve to Quicksand, and the split exists
     anyway because it is the seam: h1-h6 and body are bound to these in
     ./base.css, so no call site ever names a face, and adopting a second one
     is a one-line edit here rather than a forty-file sweep.
     display: every heading h1-h6, marketing and dashboard alike, plus every
       numeric figure — see the `figures` utility in ./utilities.css.
     body: everything else — copy, buttons, forms, tables, labels.
     named by ROLE — the mirror of the decorative color layer, which is named
     by hue precisely because a role name would imply the semantic set can
     reach for it. display-vs-body is a role, so the semantic faces take role
     names and the decorative one keeps its face name (--font-gochi below).
     ledger entry in packages/brand/design-system.md. */
  --font-display: Quicksand Variable, sans-serif;
  --font-body: Quicksand Variable, sans-serif;

  /* the handwritten aside. named by face, not by role: it is the decorative
     one-off, so a role name would put it in the semantic set. */
  --font-gochi: Gochi Hand, cursive;

  /* the --font-* namespace is NOT closed the way --text-*, --font-weight-*,
     --leading-* and --tracking-* above are: clearing it would take the three
     faces down with it and leave nothing to name. so `font-mono` otherwise
     resolves to whatever stack tailwind ships and nobody in this repo picked.
     pinned to system mono — no third webfont: mono here carries ids, hashes
     and wallet addresses, not reading copy. */
  --font-mono:
    ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono",
    monospace;

  /* the --breakpoint-* namespace stays OPEN: tailwind's sm–2xl ladder is
     inherited, and this one is added to it, sorted in by value. ledger
     entry in packages/brand/design-system.md.
     nav: the marketing header's desktop nav, which needs more room than lg. */
  --breakpoint-nav: 75rem;

  /* the --container-* namespace stays OPEN too, and unlike the one above it
     cannot be closed: max-w-* reads the same keys across every step, so a reset
     written for the nine container-query rungs would take those widths with it.
     the sweep is the gate instead —
     apps/platform/src/__tests__/container-query-conformance.node.test.ts, ledger
     entry beside the breakpoints in packages/brand/design-system.md. */
}

/* the embed's two accent slots. this package references them — btn-form-primary,
   the form-* color utilities, LoaderRing's to-(--form-primary) — so it ships the
   defaults rather than borrowing them from a consumer: any host that isn't
   platform would otherwise paint those surfaces with an unset var. a host
   overrides them per embed (platform drives them from don.config.accent_primary
   and additionally remaps --ring onto --form-primary inside #donation-container).
   declared after the brand palette import in ./index.css, so --primary and
   --secondary already resolve. */
:root {
  --form-primary: var(--primary);
  --form-secondary: var(--secondary);
}

@theme inline {
  /* the 60 ramp steps, so a step can be named at a call site: bg-gray-3,
     text-gray-11, border-gray-6. steps for surfaces, names for meaning — the
     semantic tokens below are aliases onto these same steps, and both layers
     stay spendable.

     the scale names collide with tailwind's own (blue, gray, green, red,
     amber) and the collision is harmless because the step numbers do not:
     ours run 1-12, tailwind's 50-950. `blue-600` still fails to compile
     against the --color-*: initial reset above, and `blue-9` is ours. a
     mistyped `gray-950` is therefore a build error, not a stray hue. */
  --color-blue-1: var(--blue-1);
  --color-blue-2: var(--blue-2);
  --color-blue-3: var(--blue-3);
  --color-blue-4: var(--blue-4);
  --color-blue-5: var(--blue-5);
  --color-blue-6: var(--blue-6);
  --color-blue-7: var(--blue-7);
  --color-blue-8: var(--blue-8);
  --color-blue-9: var(--blue-9);
  --color-blue-10: var(--blue-10);
  --color-blue-11: var(--blue-11);
  --color-blue-12: var(--blue-12);

  --color-red-1: var(--red-1);
  --color-red-2: var(--red-2);
  --color-red-3: var(--red-3);
  --color-red-4: var(--red-4);
  --color-red-5: var(--red-5);
  --color-red-6: var(--red-6);
  --color-red-7: var(--red-7);
  --color-red-8: var(--red-8);
  --color-red-9: var(--red-9);
  --color-red-10: var(--red-10);
  --color-red-11: var(--red-11);
  --color-red-12: var(--red-12);

  --color-green-1: var(--green-1);
  --color-green-2: var(--green-2);
  --color-green-3: var(--green-3);
  --color-green-4: var(--green-4);
  --color-green-5: var(--green-5);
  --color-green-6: var(--green-6);
  --color-green-7: var(--green-7);
  --color-green-8: var(--green-8);
  --color-green-9: var(--green-9);
  --color-green-10: var(--green-10);
  --color-green-11: var(--green-11);
  --color-green-12: var(--green-12);

  --color-amber-1: var(--amber-1);
  --color-amber-2: var(--amber-2);
  --color-amber-3: var(--amber-3);
  --color-amber-4: var(--amber-4);
  --color-amber-5: var(--amber-5);
  --color-amber-6: var(--amber-6);
  --color-amber-7: var(--amber-7);
  --color-amber-8: var(--amber-8);
  --color-amber-9: var(--amber-9);
  --color-amber-10: var(--amber-10);
  --color-amber-11: var(--amber-11);
  --color-amber-12: var(--amber-12);

  --color-gray-1: var(--gray-1);
  --color-gray-2: var(--gray-2);
  --color-gray-3: var(--gray-3);
  --color-gray-4: var(--gray-4);
  --color-gray-5: var(--gray-5);
  --color-gray-6: var(--gray-6);
  --color-gray-7: var(--gray-7);
  --color-gray-8: var(--gray-8);
  --color-gray-9: var(--gray-9);
  --color-gray-10: var(--gray-10);
  --color-gray-11: var(--gray-11);
  --color-gray-12: var(--gray-12);

  /* neutral ink and neutral lines have no token and no utility: a name like
     --fg or --muted-fg spells a rung on the grey scale and nothing else, so
     the call site names the step instead: text-gray-12 body, text-gray-11
     de-emphasised, bg-gray-3 a disabled fill. `text-fg` and
     `text-muted-fg` fail to compile rather than drifting back in beside their
     own step names. closed the same way --radius-* and the type ladders above
     are.
     --border is the exception and still exists, because it is not a constant:
     `surface-primary` rebinds it so hairlines inside a brand fill are drawn
     against that fill instead of against the page. it has no utility for the
     same reason the others don't — the token is read by the base `*` rule,
     which is what makes the rebind reach every element inside.
     --hairline and --input are the two neutral edges that DO have names, and
     each is one job on the radix scale rather than a rung: --hairline is the
     edge of something you can't operate (step 6 — a card, a header's rule, a
     divider), --input the edge of a field, checkbox or radio (radix's
     interactive-border step 7, hovered 8). a button's edge is the same 7/8
     spelled as the step, border-gray-7: it is not a field's edge. */
  --color-background: var(--background);
  --color-card: var(--card);
  --color-panel: var(--panel);
  --color-popover: var(--popover);
  /* `border-hairline` / `divide-hairline`: a card's edge and every line inside
     one. */
  --color-hairline: var(--hairline);
  --color-input: var(--input);
  --color-input-hover: var(--input-hover);
  --color-primary: var(--primary);
  --color-primary-fg: var(--primary-fg);
  --color-primary-deep: var(--primary-deep);
  --color-band: var(--band);
  --color-secondary: var(--secondary);
  --color-secondary-hover: var(--secondary-hover);
  --color-secondary-active: var(--secondary-active);
  --color-destructive: var(--destructive);
  --color-destructive-fg: var(--destructive-fg);
  --color-destructive-subtle: var(--destructive-subtle);
  --color-destructive-subtle-fg: var(--destructive-subtle-fg);
  --color-destructive-subtle-active: var(--destructive-subtle-active);
  --color-success: var(--success);
  --color-success-fg: var(--success-fg);
  --color-success-subtle: var(--success-subtle);
  --color-success-subtle-fg: var(--success-subtle-fg);
  --color-warning: var(--warning);
  --color-warning-fg: var(--warning-fg);
  --color-warning-subtle: var(--warning-subtle);
  --color-warning-subtle-fg: var(--warning-subtle-fg);
  --color-surface: var(--surface);
  --color-ring: var(--ring);
  --color-overlay: var(--overlay);
  --color-primary-ring: var(--primary-ring);
  --color-primary-border: var(--primary-border);
  --color-form-primary: var(--form-primary);
  --color-form-secondary: var(--form-secondary);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  /* the radius ladder is closed, the same way --color-* is. this repo has TWO
     corners: `rounded`, bound to --radius, for a control or a well, and
     `rounded-card`, bound to --radius-card, for a container or a floating
     layer — both by @utility in styles/utilities.css.
     the seven steps this scale would define are fractions and multiples of
     that one value (1.6px / 2.4px / 3.2px …) — near-sharp corners nobody picks
     on purpose, and they accumulate silently. resetting the scale makes
     `rounded-sm` and friends fail to
     compile instead of drifting silently. `rounded-full` and `rounded-none`
     are unaffected: v4 emits those from literals, not from this scale. */
  --radius-*: initial;

  /* both shadow namespaces are closed, the same way --color-* and --radius-*
     are, and this pair MUST stay above the declarations below — a reset written
     under them clears the ladder it exists to protect, with no build error and
     no shadow.

     what closing them buys: every stock name (`shadow-md`, `shadow-2xl`,
     `shadow-inner`) and the deprecated bare `--shadow` key match no rule, so
     depth cannot be re-picked by eye one call site at a time. what a call site
     is left with is exactly the ladder declared below — the floating level,
     the recessed pair, the one marketing lift and the one handle affordance —
     and the flush level, which is written by not writing a shadow at all.
     `shadow-none` survives — v4 emits it from a literal, not from this scale —
     so the sweep below is what keeps it out of a call site.

     it does NOT reach `shadow-[…]`. an arbitrary value is compiled straight
     from the bracket and never consults the theme, so the bracket half of this
     gate is a filesystem sweep, not the compiler —
     apps/platform/src/__tests__/elevation-conformance.node.test.ts.

     --drop-shadow-* is a sibling namespace and stays OPEN on purpose: two sites
     lay white copy over a photograph (routes/unlock-us-donations/hero.tsx), and
     a filter follows the glyph outlines where a box-shadow cannot. that is text
     legibility, not a level, so it has no token here to converge on. */
  --shadow-*: initial;
  --inset-shadow-*: initial;

  /* the elevation set: four levels a thing can sit at, plus one treatment that
     is deliberately not a rung of them. a call site spends ONE name — the tint
     lives inside the token, never as a `shadow-<color>` modifier written beside
     it, because a level paired with a hand-picked color is two decisions again.

     flush — in the document flow: a card, a well, a row, a form control. a
       card separates by its step-2 fill and its step-6 --hairline edge, a well
       by its fill (--panel is gray-3, one rung in from the card) and a control
       by its --input edge. it has NO token, on purpose:
       nothing would ever spend it, because flush is written by writing no
       shadow at all. `shadow-none` is not the spelling either — with the
       namespace closed there is nothing left for it to switch off but a named
       level, and a level that has to be cancelled at the call site is the wrong
       level there. the rule is the half of a level that goes missing, so it is
       written here and in the ledger rather than left implied by an absent
       name.
       the in-flow card carries no shadow: radix finds it by its step-6 edge,
       and the elevation sweep fails a `shadow-card` written anywhere.
     floating — hovers over content, transient, no scrim: menu, dropdown,
       combobox and select popup, tooltip, hovercard, toast, and a sticky header
       once it is stuck. --popover fill, --shadow-floating, and z-floating
       below.
     modal — covers the page behind a scrim: dialog, drawer, route-modal.
       radix themes' panel plus shadow: the --popover fill and the same
       --shadow-floating, with --overlay (declared in
       packages/brand/src/colors.css) behind it and z-scrim and z-modal for
       order. there is deliberately no --shadow-modal: the floating rung is
       the one shadow a layer over the page carries, and modal_box
       (helpers/modal-box.ts) spends it.
     the recessed pair — a track a control sits IN (slider, progress bar, switch)
       and the fill that rides raised inside it. inward depth, the mirror of
       floating: --inset-shadow-track and --shadow-track-fill.

     the values are the dominant spelling already in the tree, transcribed from
     tailwind's own defaults rather than retuned — --shadow-floating is
     `shadow-lg`, --inset-shadow-track is `shadow-inner`, --shadow-track-fill is
     `shadow-xs`. codifying the majority is what keeps the migration onto these
     names a pixel change at the outliers only.
     the shadow COLOR is the ramp's darkest rung at those same alphas. no rung
     of the ramp is an alpha black, so the alpha is made rather than picked —
     the construction --overlay (packages/brand/src/colors.css) already uses to
     reach a translucent value off a solid step. this ramp's grey carries a blue
     cast, so every floating layer, track and handle reads faintly blue rather
     than neutral: deliberate, not a tint to correct.

     --inset-shadow-track sits in the --inset-shadow-* namespace rather than
     --shadow-*, and that is not cosmetic: the two are separate box-shadow slots
     that compose, while `shadow-inner` is a DEPRECATED alias v4 still carries in
     the --shadow-* namespace. same paint today, and it outlives the alias. */
  --shadow-floating:
    0 10px 15px -3px color-mix(in oklch, var(--gray-12) 10%, transparent),
    0 4px 6px -4px color-mix(in oklch, var(--gray-12) 10%, transparent);
  --inset-shadow-track: inset 0 2px 4px 0
    color-mix(in oklch, var(--gray-12) 5%, transparent);
  --shadow-track-fill: 0 1px 2px 0
    color-mix(in oklch, var(--gray-12) 5%, transparent);

  /* the marketing lift — a treatment, not a rung, and named apart precisely so
     the app cannot pick it up by reaching for a level. one surface on the
     marketing pages carries a deliberate glow: a photograph (or the skeleton
     standing in for one). a marketing card does not: it is the same edged
     card as every other, and a solid control carries no shadow. it was
     spelled `shadow-2xl shadow-black/10`; folding the tint into the token is
     what makes it one class instead of two, and what stops a second opacity
     being picked by eye.
     the color-mix() is exactly what v4 compiles a `/<alpha>` shadow modifier to,
     so this paints identically to the pair it replaces. --color-black is
     #000101, not pure black — `shadow-black/10` always read that token, and
     naming it here keeps it reading the same one. */
  --shadow-lift-media: 0 25px 50px -12px
    color-mix(in oklab, var(--color-black) 10%, transparent);

  /* an affordance, NOT a rung — do not reach for it to raise something. the
     one consumer is the img-editor's 8px white crop handle
     (components/img-editor/cropper.tsx), drawn over a donor's own uploaded
     photograph, where the ground is arbitrary and a white dot on pale imagery
     has no edge at all. the shadow is there to give it one; depth is a side
     effect. the same legibility problem is recorded for the selection edge in
     that file's own comment.
     it exists as a name because the call site spelled a bare `shadow`, which
     reads the DEFAULT --shadow key — deprecated in v4, and stripped along with
     the rest of the namespace by the reset, silently and with no build error.
     the geometry and the alphas are exactly what that key resolved to at the
     pinned version, so naming it moved nothing; the hue is the ramp's, with the
     rest of the elevation set above. */
  --shadow-handle:
    0 1px 3px 0 color-mix(in oklch, var(--gray-12) 10%, transparent),
    0 1px 2px -1px color-mix(in oklch, var(--gray-12) 10%, transparent);

  /* the stacking ladder. each elevation level binds its own step, ordered so a
     popup opened INSIDE a dialog clears it without a hand-picked value — which
     is the entire reason a combobox in a modal used to be spelled `z-51`.
     bounded on purpose: these six name the elevation layers and nothing else.
     the z-* namespace is NOT reset, so `z-10` and friends still compile, and
     the values that stack siblings inside one component stay untouched.
     --z-index-* is a real v4 namespace — the `z` utility declares it as its
     theme key — but it is absent from the namespace table in the docs, so this
     is verified against the compiler at the pinned version, not read off that
     table. */
  /* two rungs for pinned chrome, not one: a page can pin a header AND a bar
     beneath it (the checklist's progress bar sticks at top-16, under the 4rem
     marketing header). one step for both leaves the pair resolving by document
     order, so the sub-bar wins when it comes later in the tree and slides over
     the header it is supposed to sit under. the rule is fixed: a pinned header
     is always above a bar pinned beneath it. */
  --z-index-subbar: 20; /* a bar pinned BENEATH a pinned header */
  --z-index-sticky: 30; /* page chrome that pins: the header (the announcement bar scrolls away) */
  --z-index-scrim: 40; /* the --overlay a modal lays over the page */
  --z-index-modal: 50; /* dialog, drawer, route-modal — above their own scrim */
  --z-index-floating: 60; /* menu, popup, tooltip, toast — above an open modal */
  --z-index-top: 100; /* the one step above everything: route-load progress */

  /* the speed ladder. three steps, and they are the three values the app and
     the keyframes below already ran at — the ladder names them, it does not
     design them.

     the two --default-transition-* keys carry more than their two lines
     suggest: the overwhelming majority of the app's transitions name neither a
     duration nor an easing, so every one of them reads these. tailwind's own
     defaults are 150ms and its in-out curve, which is what an unspelled
     transition takes while nothing here declares them — the right values,
     arrived at by accident and retunable nowhere.

     duration is the one axis on this page tailwind gives no theme NAMESPACE
     for — `duration-<number>` is a bare value, not a scale lookup — so there
     is nothing to reset to `initial` and `duration-200` still compiles. the
     three steps are bound to `duration-fast|base|slow` by @utility in
     styles/utilities.css, the same way `rounded` is bound to --radius, and
     the sweep rather than the compiler is what keeps a literal out of a call
     site.

     easing is a real namespace, and tailwind's three curves are exactly the
     three roles this system has, so the set is inherited unchanged rather
     than redeclared:
       ease-out     something entering        (--animate-*-in below)
       ease-in      something leaving         (--animate-*-out below)
       ease-in-out  a control moving between two resting states — a hover
                    colour, a toggle thumb, a chevron flipping
     the third is the default, so a call site writes no easing for it at all —
     which is what keeps an explicit ease-out or ease-in meaning enter or exit
     and nothing else. */
  --duration-fast: 150ms; /* a control acknowledging you, and a popup */
  --duration-base: 200ms; /* an element entering or leaving the page */
  --duration-slow: 300ms; /* something changing size in the flow */

  --default-transition-duration: var(--duration-fast);
  --default-transition-timing-function: var(--ease-in-out);

  /*
   * ark overlay/accordion animations.
   * inline `transition-[...] data-[state=closed]:...` only animates exit;
   * keyframes triggered by data-state animate both directions.
   * usage: `data-[state=open]:animate-popup-in data-[state=closed]:animate-popup-out`.
   * for accordion: `data-[state=open]:animate-accordion-down data-[state=closed]:animate-accordion-up`
   * with `overflow-hidden` on item-content (--height is set during transitions).
   */
  --animate-overlay-in: overlay-in var(--duration-base) var(--ease-out);
  --animate-overlay-out: overlay-out var(--duration-base) var(--ease-in);
  --animate-popup-in: popup-in var(--duration-fast) var(--ease-out);
  --animate-popup-out: popup-out var(--duration-fast) var(--ease-in);
  --animate-accordion-down: accordion-down var(--duration-slow) var(--ease-out);
  --animate-accordion-up: accordion-up var(--duration-slow) var(--ease-out);
  /* ark marquee: vars (--marquee-duration/delay/loop-count) provided by machine */
  --animate-marquee-y: marqueeY var(--marquee-duration) linear
    var(--marquee-delay) var(--marquee-loop-count);
  --animate-marquee-x: marqueeX var(--marquee-duration) linear
    var(--marquee-delay) var(--marquee-loop-count);

  @keyframes overlay-in {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
  @keyframes overlay-out {
    from {
      opacity: 1;
    }
    to {
      opacity: 0;
    }
  }
  @keyframes popup-in {
    from {
      opacity: 0;
      scale: 0.95;
    }
    to {
      opacity: 1;
      scale: 1;
    }
  }
  @keyframes popup-out {
    from {
      opacity: 1;
      scale: 1;
    }
    to {
      opacity: 0;
      scale: 0.95;
    }
  }
  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--height);
    }
  }
  @keyframes accordion-up {
    from {
      height: var(--height);
    }
    to {
      height: 0;
    }
  }
  @keyframes marqueeY {
    from {
      transform: translateY(0%);
    }
    to {
      transform: translateY(var(--marquee-translate));
    }
  }
  @keyframes marqueeX {
    from {
      transform: translateX(0%);
    }
    to {
      transform: translateX(var(--marquee-translate));
    }
  }
}

/* the reduced-motion guard is on the ladder, not on the call sites. every
   transition and every --animate-* above spends one of the three named speeds,
   so collapsing the three here reaches all of them and none of them needs a
   `motion-reduce:` variant of its own. it covers the ladder and only the
   ladder: motion that never reads a named speed is untouched (see
   packages/brand/design-system.md → motion → what is still open). it sits
   outside @theme because a media query cannot live inside one, and unlayered,
   so it wins over the `@layer theme` :root tailwind emits the ladder into.

   0.01ms rather than 0: a zero-duration transition never starts and fires no
   transitionend, so anything waiting on that event waits forever. a near-zero
   one still completes, still fires, and is invisible.

   durations only: there is nothing for a 0.01ms easing to shape. the marquee
   keeps its own `motion-reduce:animate-none`: its duration comes from the ark
   machine's var rather than this ladder, and it is a continuous loop rather
   than a state change.

   tailwind's own spin and pulse are that same continuous loop, and they stop
   here rather than shorten. they never touch the ladder — 1s and 2s out of
   tailwind's default theme, and no named speed reads as a revolution — and a
   collapsed duration only stills a loop that ends: an infinite one at 0.01ms
   cycles faster than a frame, so every paint samples an arbitrary angle and
   the spinner jitters instead of stopping. `none` is what the marquee spells
   at its call site; these two are theme keys, so one line each reaches every
   `animate-spin` and `animate-pulse` in the tree. tailwind emits them into
   `@layer theme`, which is what this unlayered :root already outranks. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --duration-fast: 0.01ms;
    --duration-base: 0.01ms;
    --duration-slow: 0.01ms;

    --animate-spin: none;
    --animate-pulse: none;
  }
}
